func loadINIFile(path string) (*INIFile, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	ini := &INIFile{
		Root:     map[string]string{},
		Sections: map[string]map[string]string{},
	}

	currentSection := ""
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			currentSection = strings.ToLower(strings.TrimSpace(line[1 : len(line)-1]))
			if _, ok := ini.Sections[currentSection]; !ok {
				ini.Sections[currentSection] = map[string]string{}
				ini.SectionOrder = append(ini.SectionOrder, currentSection)
			}
			continue
		}

		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			continue
		}

		key := strings.ToLower(strings.TrimSpace(parts[0]))
		value := stripInlineComment(strings.TrimSpace(parts[1]))
		if currentSection == "" {
			ini.Root[key] = value
		} else {
			ini.Sections[currentSection][key] = value
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return ini, nil
}

