package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"time"
	"unicode/utf8"
	"unsafe"
)

var errAppExit = errors.New("app exit")

type FocusArea int

const (
	FocusSections FocusArea = iota
	FocusTags
	FocusMain
)

type App struct {
	cfg            Config
	format         LogNameFormat
	repo           *Repository
	focus          FocusArea
	displayYear    int
	cursorDate     time.Time
	sectionItems   []MenuItem
	tagItems       []MenuItem
	sectionIndex   int
	tagIndex       int
	scratchpadMode bool
	screen         *TerminalSession
}

func NewApp(cfg Config, repo *Repository) *App {
	format, err := compileLogNameFormat(cfg.LogNameFormat)
	if err != nil {
		panic(err)
	}
	now := time.Now().In(time.Local)
	app := &App{
		cfg:         cfg,
		format:      format,
		repo:        repo,
		focus:       FocusSections,
		displayYear: now.Year(),
		cursorDate:  time.Date(now.Year(), now.Month(), now.Day(), 12, 0, 0, 0, time.Local),
	}
	app.rebuildMenus()
	return app
}

func (app *App) Run() error {
	if isTerminal(os.Stdin.Fd()) && isTerminal(os.Stdout.Fd()) {
		session, err := NewTerminalSession(int(os.Stdin.Fd()), os.Stdout)
		if err != nil {
			return err
		}
		app.screen = session
		defer session.Close()
	} else {
		fmt.Fprint(os.Stdout, app.renderFrame(120, 30))
		return nil
	}

	reader := bufio.NewReader(os.Stdin)
	if err := app.redraw(); err != nil {
		return err
	}

	for {
		key, err := readKey(reader)
		if err != nil {
			return nil
		}
		if exit := app.handleKey(key); exit {
			return errAppExit
		}
		if err := app.redraw(); err != nil {
			return err
		}
	}
}

func (app *App) handleKey(key Key) bool {
	switch key.Kind {
	case KeyCtrlC, KeyQuit:
		return true
	case KeyTab:
		app.focus = (app.focus + 1) % 3
	case KeyBackTab:
		if app.focus == 0 {
			app.focus = 2
		} else {
			app.focus--
		}
	case KeyToggleScratchpad:
		app.scratchpadMode = !app.scratchpadMode
	case KeyNextYear:
		app.displayYear++
		app.cursorDate = time.Date(app.displayYear, app.cursorDate.Month(), minInt(app.cursorDate.Day(), daysInMonth(app.displayYear, app.cursorDate.Month())), 12, 0, 0, 0, time.Local)
		app.rebuildMenus()
	case KeyPrevYear:
		app.displayYear--
		app.cursorDate = time.Date(app.displayYear, app.cursorDate.Month(), minInt(app.cursorDate.Day(), daysInMonth(app.displayYear, app.cursorDate.Month())), 12, 0, 0, 0, time.Local)
		app.rebuildMenus()
	case KeyResetToday:
		now := time.Now().In(time.Local)
		app.displayYear = now.Year()
		app.cursorDate = time.Date(now.Year(), now.Month(), now.Day(), 12, 0, 0, 0, time.Local)
		app.rebuildMenus()
	case KeyDelete:
		if !app.scratchpadMode && app.focus == FocusMain {
			_ = os.Remove(app.currentLogPath())
			_ = app.refresh()
		}
	case KeyEnter:
		if app.scratchpadMode {
			_ = app.openEditor(app.scratchpadPath())
			_ = app.refresh()
		} else if app.focus == FocusMain {
			_ = app.openEditor(app.currentLogPath())
			_ = app.refresh()
		}
	case KeyUp:
		app.navigateUp()
	case KeyDown:
		app.navigateDown()
	case KeyLeft:
		app.navigateLeft()
	case KeyRight:
		app.navigateRight()
	}

	return false
}

func (app *App) navigateUp() {
	switch {
	case app.scratchpadMode:
		return
	case app.focus == FocusSections:
		if app.sectionIndex > 0 {
			app.sectionIndex--
			app.tagIndex = 0
			app.rebuildMenus()
		}
	case app.focus == FocusTags:
		if app.tagIndex > 0 {
			app.tagIndex--
		}
	case app.focus == FocusMain:
		app.cursorDate = app.cursorDate.AddDate(0, 0, -7)
		app.displayYear = app.cursorDate.Year()
		app.rebuildMenus()
	}
}

func (app *App) navigateDown() {
	switch {
	case app.scratchpadMode:
		return
	case app.focus == FocusSections:
		if app.sectionIndex+1 < len(app.sectionItems) {
			app.sectionIndex++
			app.tagIndex = 0
			app.rebuildMenus()
		}
	case app.focus == FocusTags:
		if app.tagIndex+1 < len(app.tagItems) {
			app.tagIndex++
		}
	case app.focus == FocusMain:
		app.cursorDate = app.cursorDate.AddDate(0, 0, 7)
		app.displayYear = app.cursorDate.Year()
		app.rebuildMenus()
	}
}

func (app *App) navigateLeft() {
	if app.scratchpadMode {
		return
	}
	if app.focus == FocusMain {
		app.cursorDate = app.cursorDate.AddDate(0, 0, -1)
		app.displayYear = app.cursorDate.Year()
		app.rebuildMenus()
	}
}

func (app *App) navigateRight() {
	if app.scratchpadMode {
		return
	}
	if app.focus == FocusMain {
		app.cursorDate = app.cursorDate.AddDate(0, 0, 1)
		app.displayYear = app.cursorDate.Year()
		app.rebuildMenus()
	}
}

func (app *App) refresh() error {
	repo, err := ScanRepository(app.cfg)
	if err != nil {
		return err
	}
	app.repo = repo
	app.rebuildMenus()
	return nil
}

func (app *App) selectedSectionValue() string {
